import { type AnyColumn, Column } from '~/column.ts';
import { entityKind, is } from '~/entity.ts';
import { type DriverValueDecoder, SQL, sql, type SQLChunk, type SQLWrapper } from '../sql.ts';

type FrameBoundaryKind = 'unboundedPreceding' | 'preceding' | 'currentRow' | 'following' | 'unboundedFollowing';

const boundaryRank: Record<FrameBoundaryKind, number> = {
	unboundedPreceding: 0,
	preceding: 1,
	currentRow: 2,
	following: 3,
	unboundedFollowing: 4,
};

/** A single boundary of a window frame, e.g. `unbounded preceding` or `3 following`. */
export class WindowFrameBoundary implements SQLWrapper {
	static readonly [entityKind]: string = 'WindowFrameBoundary';

	constructor(readonly kind: FrameBoundaryKind, readonly offset?: number) {}

	getSQL(): SQL {
		switch (this.kind) {
			case 'unboundedPreceding': {
				return sql.raw('unbounded preceding');
			}
			case 'preceding': {
				return sql.raw(`${this.offset} preceding`);
			}
			case 'currentRow': {
				return sql.raw('current row');
			}
			case 'following': {
				return sql.raw(`${this.offset} following`);
			}
			case 'unboundedFollowing': {
				return sql.raw('unbounded following');
			}
		}
	}
}

/** Frame boundary `unbounded preceding`. */
export const unboundedPreceding: WindowFrameBoundary = new WindowFrameBoundary('unboundedPreceding');
/** Frame boundary `current row`. */
export const currentRow: WindowFrameBoundary = new WindowFrameBoundary('currentRow');
/** Frame boundary `unbounded following`. */
export const unboundedFollowing: WindowFrameBoundary = new WindowFrameBoundary('unboundedFollowing');

function assertNonNegativeInteger(fnName: string, value: unknown): asserts value is number {
	if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
		throw new Error(`${fnName}(): expected a non-negative integer, received ${String(value)}`);
	}
}

function assertPositiveInteger(fnName: string, value: unknown): asserts value is number {
	if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0) {
		throw new Error(`${fnName}(): expected a positive integer, received ${String(value)}`);
	}
}

/** Frame boundary `<offset> preceding`. */
export function preceding(offset: number): WindowFrameBoundary {
	assertNonNegativeInteger('preceding', offset);
	return new WindowFrameBoundary('preceding', offset);
}

/** Frame boundary `<offset> following`. */
export function following(offset: number): WindowFrameBoundary {
	assertNonNegativeInteger('following', offset);
	return new WindowFrameBoundary('following', offset);
}

export interface WindowFrameBounds {
	from: WindowFrameBoundary;
	to?: WindowFrameBoundary;
}

export type WindowFrameMode = 'rows' | 'range';

/** A window frame clause, e.g. `rows between unbounded preceding and current row`. */
export class WindowFrame implements SQLWrapper {
	static readonly [entityKind]: string = 'WindowFrame';

	constructor(readonly mode: WindowFrameMode, readonly bounds: WindowFrameBounds) {}

	getSQL(): SQL {
		const { from, to } = this.bounds;
		if (to === undefined) {
			return sql`${sql.raw(this.mode)} ${from}`;
		}
		return sql`${sql.raw(this.mode)} between ${from} and ${to}`;
	}
}

/** Position of a boundary within the frame ordering; a larger value is later. */
function boundaryPosition(boundary: WindowFrameBoundary): [number, number] {
	const offset = boundary.offset ?? 0;
	// `5 preceding` comes before `3 preceding`, `3 following` comes before `5 following`
	return [boundaryRank[boundary.kind], boundary.kind === 'preceding' ? -offset : offset];
}

function createFrame(mode: WindowFrameMode, bounds: WindowFrameBounds): WindowFrame {
	const { from, to } = bounds ?? {};
	if (!is(from, WindowFrameBoundary)) {
		throw new Error(`${mode}(): "from" must be a frame boundary`);
	}
	if (to !== undefined && !is(to, WindowFrameBoundary)) {
		throw new Error(`${mode}(): "to" must be a frame boundary`);
	}
	if (from.kind === 'unboundedFollowing') {
		throw new Error(`${mode}(): "from" cannot be unboundedFollowing`);
	}
	if (to === undefined) {
		if (from.kind === 'following') {
			throw new Error(`${mode}(): "from" cannot be a following boundary when "to" is omitted`);
		}
	} else {
		if (to.kind === 'unboundedPreceding') {
			throw new Error(`${mode}(): "to" cannot be unboundedPreceding`);
		}
		const [fromRank, fromOffset] = boundaryPosition(from);
		const [toRank, toOffset] = boundaryPosition(to);
		if (fromRank > toRank || (fromRank === toRank && fromOffset > toOffset)) {
			throw new Error(`${mode}(): "from" boundary must not come after the "to" boundary`);
		}
	}
	return new WindowFrame(mode, bounds);
}

/**
 * Builds a `rows` frame clause.
 *
 * ## Examples
 *
 * ```ts
 * rows({ from: unboundedPreceding, to: currentRow })
 * // rows between unbounded preceding and current row
 * ```
 */
export function rows(bounds: WindowFrameBounds): WindowFrame {
	return createFrame('rows', bounds);
}

/**
 * Builds a `range` frame clause.
 *
 * ## Examples
 *
 * ```ts
 * range({ from: preceding(3), to: following(3) })
 * // range between 3 preceding and 3 following
 * ```
 */
export function range(bounds: WindowFrameBounds): WindowFrame {
	return createFrame('range', bounds);
}

export interface WindowSpec {
	partitionBy?: SQLWrapper | SQLWrapper[];
	orderBy?: SQLWrapper | SQLWrapper[];
	frame?: WindowFrame;
}

export interface WindowDefinition {
	name: string;
	spec: WindowSpec;
}

/** Throws if `name` cannot be used as a window name. */
export function validateWindowName(name: unknown, fnName = 'window'): asserts name is string {
	if (typeof name !== 'string' || name.length === 0) {
		throw new Error(`${fnName}(): window name must be a non-empty string`);
	}
	if (name.trim().length === 0) {
		throw new Error(`${fnName}(): window name must not consist only of whitespace`);
	}
}

function toArray<T>(value: T | T[] | undefined): T[] {
	if (value === undefined) return [];
	return Array.isArray(value) ? value : [value];
}

/** Builds the contents of a window specification, without the surrounding parentheses. */
export function buildWindowSpec(spec: WindowSpec = {}): SQL {
	const parts: SQL[] = [];
	const partitionBy = toArray(spec.partitionBy);
	if (partitionBy.length > 0) {
		parts.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
	}
	const orderBy = toArray(spec.orderBy);
	if (orderBy.length > 0) {
		parts.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
	}
	if (spec.frame !== undefined) {
		parts.push(spec.frame.getSQL());
	}
	return sql.join(parts, sql` `);
}

/** Builds the ` window "name" as (...)` clause of a select query. */
export function buildWindowClause(windows: WindowDefinition[] | undefined): SQL | undefined {
	if (!windows || windows.length === 0) return undefined;
	const definitions = windows.map(({ name, spec }) => sql`${sql.identifier(name)} as (${buildWindowSpec(spec)})`);
	return sql` window ${sql.join(definitions, sql`, `)}`;
}

/** Adds or replaces a named window definition in `windows`. */
export function addWindowDefinition(
	windows: WindowDefinition[] | undefined,
	name: string,
	spec: WindowSpec,
): WindowDefinition[] {
	validateWindowName(name);
	const result = (windows ?? []).filter((w) => w.name !== name);
	result.push({ name, spec });
	return result;
}

/**
 * A window function call that must be completed with `.over()`.
 */
export class WindowFunction<T = unknown> {
	static readonly [entityKind]: string = 'WindowFunction';

	declare readonly _: {
		readonly type: T;
	};

	constructor(
		readonly fnName: string,
		readonly call: SQL,
		readonly decoder?: DriverValueDecoder<any, any>,
	) {}

	/**
	 * Applies the window function over an inline window specification or a named window.
	 *
	 * ## Examples
	 *
	 * ```ts
	 * rowNumber().over() // row_number() over ()
	 * rowNumber().over({ partitionBy: t.a, orderBy: desc(t.b) })
	 * rowNumber().over('w') // row_number() over "w"
	 * ```
	 */
	over(spec?: WindowSpec | string): SQL<T> {
		let result: SQL;
		if (typeof spec === 'string') {
			validateWindowName(spec, 'over');
			result = sql`${this.call} over ${sql.identifier(spec)}`;
		} else {
			result = sql`${this.call} over (${buildWindowSpec(spec)})`;
		}
		if (this.decoder) {
			result = result.mapWith(this.decoder);
		}
		return result as SQL<T>;
	}
}

type InferData<T> = T extends AnyColumn ? T['_']['data']
	: T extends SQL<infer U> ? U
	: T extends SQL.Aliased<infer U> ? U
	: unknown;

function decoderOf(expression: SQLWrapper): DriverValueDecoder<any, any> | undefined {
	if (is(expression, Column)) return expression;
	if (is(expression, SQL)) return expression.decoder;
	if (is(expression, SQL.Aliased)) return expression.sql.decoder;
	return undefined;
}

const numberDecoder: DriverValueDecoder<number, any> = { mapFromDriverValue: Number };
const stringDecoder: DriverValueDecoder<string, any> = { mapFromDriverValue: String };

/** Renders a positional argument; numbers are always inlined and never bound as parameters. */
function positional(value: unknown): SQLChunk {
	if (typeof value === 'number') {
		if (!Number.isFinite(value)) {
			throw new Error(`Window function argument must be a finite number, received ${String(value)}`);
		}
		return sql.raw(String(value));
	}
	if (typeof value === 'bigint') {
		return sql.raw(value.toString());
	}
	return sql`${value}`;
}

function call(fnName: string, args: SQLChunk[]): SQL {
	return sql`${sql.raw(fnName)}(${sql.join(args, sql`, `)})`;
}

// Ranking functions

/** `row_number()`: number of the current row within its partition, counting from 1. */
export function rowNumber(): WindowFunction<number> {
	return new WindowFunction('rowNumber', call('row_number', []), numberDecoder);
}

/** `rank()`: rank of the current row with gaps. */
export function rank(): WindowFunction<number> {
	return new WindowFunction('rank', call('rank', []), numberDecoder);
}

/** `dense_rank()`: rank of the current row without gaps. */
export function denseRank(): WindowFunction<number> {
	return new WindowFunction('denseRank', call('dense_rank', []), numberDecoder);
}

/** `ntile(buckets)`: integer ranging from 1 to `buckets`, dividing the partition as equally as possible. */
export function ntile(buckets: number): WindowFunction<number> {
	assertPositiveInteger('ntile', buckets);
	return new WindowFunction('ntile', call('ntile', [positional(buckets)]), numberDecoder);
}

/** `percent_rank()`: relative rank of the current row, from 0 to 1. */
export function percentRank(): WindowFunction<number> {
	return new WindowFunction('percentRank', call('percent_rank', []), numberDecoder);
}

/** `cume_dist()`: cumulative distribution of the current row, from 0 to 1. */
export function cumeDist(): WindowFunction<number> {
	return new WindowFunction('cumeDist', call('cume_dist', []), numberDecoder);
}

// Offset (value access) functions

function offsetFunction(
	fnName: string,
	sqlName: string,
	expression: SQLWrapper,
	offset: number | undefined,
	defaultValue: unknown,
): WindowFunction<any> {
	const args: SQLChunk[] = [expression];
	if (offset !== undefined || defaultValue !== undefined) {
		const resolvedOffset = offset ?? 1;
		assertNonNegativeInteger(fnName, resolvedOffset);
		args.push(positional(resolvedOffset));
	}
	if (defaultValue !== undefined) {
		args.push(positional(defaultValue));
	}
	return new WindowFunction(fnName, call(sqlName, args), decoderOf(expression));
}

/**
 * `lag(expression, offset, default)`: value of `expression` at the row `offset` rows before the current row.
 * When `defaultValue` is provided, the result is not nullable.
 */
export function lag<T extends SQLWrapper>(
	expression: T,
	offset: number | undefined,
	defaultValue: NonNullable<InferData<T>> | SQLWrapper,
): WindowFunction<NonNullable<InferData<T>>>;
export function lag<T extends SQLWrapper>(expression: T, offset?: number): WindowFunction<InferData<T> | null>;
export function lag(expression: SQLWrapper, offset?: number, defaultValue?: unknown): WindowFunction<any> {
	return offsetFunction('lag', 'lag', expression, offset, defaultValue);
}

/**
 * `lead(expression, offset, default)`: value of `expression` at the row `offset` rows after the current row.
 * When `defaultValue` is provided, the result is not nullable.
 */
export function lead<T extends SQLWrapper>(
	expression: T,
	offset: number | undefined,
	defaultValue: NonNullable<InferData<T>> | SQLWrapper,
): WindowFunction<NonNullable<InferData<T>>>;
export function lead<T extends SQLWrapper>(expression: T, offset?: number): WindowFunction<InferData<T> | null>;
export function lead(expression: SQLWrapper, offset?: number, defaultValue?: unknown): WindowFunction<any> {
	return offsetFunction('lead', 'lead', expression, offset, defaultValue);
}

/** `first_value(expression)`: value of `expression` at the first row of the window frame. */
export function firstValue<T extends SQLWrapper>(expression: T): WindowFunction<InferData<T> | null> {
	return new WindowFunction('firstValue', call('first_value', [expression]), decoderOf(expression));
}

/** `last_value(expression)`: value of `expression` at the last row of the window frame. */
export function lastValue<T extends SQLWrapper>(expression: T): WindowFunction<InferData<T> | null> {
	return new WindowFunction('lastValue', call('last_value', [expression]), decoderOf(expression));
}

/** `nth_value(expression, n)`: value of `expression` at the `n`-th row of the window frame, counting from 1. */
export function nthValue<T extends SQLWrapper>(expression: T, n: number): WindowFunction<InferData<T> | null> {
	assertPositiveInteger('nthValue', n);
	return new WindowFunction('nthValue', call('nth_value', [expression, positional(n)]), decoderOf(expression));
}

// Aggregate window functions

/** `sum(expression)` used as a window function. */
export function windowSum(expression: SQLWrapper): WindowFunction<string | null> {
	return new WindowFunction('windowSum', call('sum', [expression]), stringDecoder);
}

/** `avg(expression)` used as a window function. */
export function windowAvg(expression: SQLWrapper): WindowFunction<string | null> {
	return new WindowFunction('windowAvg', call('avg', [expression]), stringDecoder);
}

/** `min(expression)` used as a window function. */
export function windowMin<T extends SQLWrapper>(
	expression: T,
): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null> {
	return new WindowFunction(
		'windowMin',
		call('min', [expression]),
		is(expression, Column) ? expression : stringDecoder,
	);
}

/** `max(expression)` used as a window function. */
export function windowMax<T extends SQLWrapper>(
	expression: T,
): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null> {
	return new WindowFunction(
		'windowMax',
		call('max', [expression]),
		is(expression, Column) ? expression : stringDecoder,
	);
}

/** `count(expression)` used as a window function; `count(*)` when called without an argument. */
export function windowCount(expression?: SQLWrapper): WindowFunction<number> {
	return new WindowFunction(
		'windowCount',
		call('count', [expression === undefined ? sql.raw('*') : expression]),
		numberDecoder,
	);
