import { describe, expect, expectTypeOf, test } from 'vitest';
import {
	currentRow,
	cumeDist,
	denseRank,
	desc,
	firstValue,
	following,
	lag,
	lastValue,
	lead,
	nthValue,
	ntile,
	percentRank,
	preceding,
	range,
	rank,
	rowNumber,
	rows,
	unboundedFollowing,
	unboundedPreceding,
	windowAvg,
	windowCount,
	windowMax,
	windowMin,
	windowSum,
} from '~/index.ts';
import { drizzle as mysqlDrizzle } from '~/mysql2/index.ts';
import { drizzle as pgDrizzle } from '~/node-postgres/index.ts';
import { integer, pgTable, text } from '~/pg-core/index.ts';
import { drizzle as singlestoreDrizzle } from '~/singlestore/index.ts';
import { drizzle as sqliteDrizzle } from '~/better-sqlite3/index.ts';
import { int, mysqlTable } from '~/mysql-core/index.ts';
import { int as ssInt, singlestoreTable } from '~/singlestore-core/index.ts';
import { integer as sqliteInteger, sqliteTable } from '~/sqlite-core/index.ts';
import { PgDialect } from '~/pg-core/dialect.ts';
import type { SQL } from '~/sql/sql.ts';

const t = pgTable('t', {
	id: integer('id').primaryKey(),
	dept: text('dept').notNull(),
	salary: integer('salary'),
});

const dialect = new PgDialect();
const db = pgDrizzle.mock();
const q = (s: SQL) => dialect.sqlToQuery(s);

describe('window functions', () => {
	test('function names', () => {
		expect(q(rowNumber().over()).sql).toBe('row_number() over ()');
		expect(q(rank().over()).sql).toBe('rank() over ()');
		expect(q(denseRank().over()).sql).toBe('dense_rank() over ()');
		expect(q(ntile(4).over()).sql).toBe('ntile(4) over ()');
		expect(q(percentRank().over()).sql).toBe('percent_rank() over ()');
		expect(q(cumeDist().over()).sql).toBe('cume_dist() over ()');
		expect(q(lag(t.salary).over()).sql).toBe('lag("t"."salary") over ()');
		expect(q(lead(t.salary).over()).sql).toBe('lead("t"."salary") over ()');
		expect(q(firstValue(t.salary).over()).sql).toBe('first_value("t"."salary") over ()');
		expect(q(lastValue(t.salary).over()).sql).toBe('last_value("t"."salary") over ()');
		expect(q(nthValue(t.salary, 2).over()).sql).toBe('nth_value("t"."salary", 2) over ()');
		expect(q(windowSum(t.salary).over({})).sql).toBe('sum("t"."salary") over ()');
		expect(q(windowAvg(t.salary).over()).sql).toBe('avg("t"."salary") over ()');
		expect(q(windowMin(t.salary).over()).sql).toBe('min("t"."salary") over ()');
		expect(q(windowMax(t.salary).over()).sql).toBe('max("t"."salary") over ()');
		expect(q(windowCount().over()).sql).toBe('count(*) over ()');
		expect(q(windowCount(t.id).over()).sql).toBe('count("t"."id") over ()');
	});

	test('positional args are inlined, never bound', () => {
		const lagQ = q(lag(t.salary, 0, 0).over());
		expect(lagQ.sql).toBe('lag("t"."salary", 0, 0) over ()');
		expect(lagQ.params).toEqual([]);
		expect(q(lead(t.salary, 2).over()).sql).toBe('lead("t"."salary", 2) over ()');
		expect(q(lead(t.salary, undefined, 5).over()).sql).toBe('lead("t"."salary", 1, 5) over ()');
		expect(q(ntile(1).over()).params).toEqual([]);
	});

	test('validation', () => {
		expect(() => ntile(0)).toThrow(/ntile.*0/);
		expect(() => ntile(1.5)).toThrow(/ntile.*1\.5/);
		expect(() => nthValue(t.salary, -1)).toThrow(/nthValue.*-1/);
		expect(() => preceding(-1)).toThrow(/preceding/);
		expect(() => following(1.5)).toThrow(/following/);
		expect(() => rows({ from: currentRow, to: preceding(1) })).toThrow(/from/);
		expect(() => range({ from: preceding(1), to: preceding(3) })).toThrow(/from/);
		expect(() => rows({ from: following(3), to: following(1) })).toThrow(/from/);
		expect(() => db.select().from(t).window('', {})).toThrow(/non-empty/);
		expect(() => db.select().from(t).window('  ', {})).toThrow(/whitespace/);
	});

	test('inline spec with frame', () => {
		const query = q(
			windowSum(t.salary).over({
				partitionBy: t.dept,
				orderBy: [desc(t.salary), t.id],
				frame: rows({ from: unboundedPreceding, to: currentRow }),
			}),
		);
		expect(query.sql).toBe(
			'sum("t"."salary") over (partition by "t"."dept" order by "t"."salary" desc, "t"."id" rows between unbounded preceding and current row)',
		);
		expect(q(rank().over({ frame: range({ from: preceding(0), to: following(3) }) })).sql).toBe(
			'rank() over (range between 0 preceding and 3 following)',
		);
		expect(q(rank().over({ frame: rows({ from: currentRow, to: unboundedFollowing }) })).sql).toBe(
			'rank() over (rows between current row and unbounded following)',
		);
	});

	test('named windows (pg)', () => {
		const query = db.select({ id: t.id, r: rank().over('w') }).from(t)
			.window('w', { partitionBy: t.dept, orderBy: desc(t.salary) })
			.window('w2', {})
			.orderBy(t.id)
			.toSQL();
		expect(query.sql).toBe(
			'select "id", rank() over "w" from "t" window "w" as (partition by "t"."dept" order by "t"."salary" desc), "w2" as () order by "t"."id"',
		);
	});

	test('named windows across dialects', () => {
		const m = mysqlTable('t', { id: int('id') });
		expect(mysqlDrizzle.mock().select({ r: rowNumber().over('w') }).from(m).window('w', { orderBy: m.id }).toSQL().sql)
			.toBe('select row_number() over `w` from `t` window `w` as (order by `t`.`id`)');
		const s = sqliteTable('t', { id: sqliteInteger('id') });
		const sqliteDb = sqliteDrizzle(':memory:');
		expect(sqliteDb.select({ r: rowNumber().over('w') }).from(s).window('w', { orderBy: s.id }).toSQL().sql)
			.toBe('select row_number() over "w" from "t" window "w" as (order by "t"."id")');
		const ss = singlestoreTable('t', { id: ssInt('id') });
		expect(
			singlestoreDrizzle.mock().select({ r: rowNumber().over('w') }).from(ss).window('w', { orderBy: ss.id }).toSQL()
				.sql,
		).toBe('select row_number() over `w` from `t` window `w` as (order by `t`.`id`)');
	});

	test('types', () => {
		expectTypeOf(rowNumber().over()).toEqualTypeOf<SQL<number>>();
		expectTypeOf(lag(t.salary).over()).toEqualTypeOf<SQL<number | null>>();
		expectTypeOf(lag(t.salary, 1, 0).over()).toEqualTypeOf<SQL<number>>();
		expectTypeOf(lead(t.dept, 1, 'x').over()).toEqualTypeOf<SQL<string>>();
		expectTypeOf(firstValue(t.dept).over()).toEqualTypeOf<SQL<string | null>>();
		expectTypeOf(nthValue(t.id, 2).over()).toEqualTypeOf<SQL<number | null>>();
	});
});

